    drawing=new DrawView(this);drawing.setBackgroundColor(Color.WHITE);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,0,1);cp.setMargins(dp(2),dp(3),dp(2),dp(4));root.addView(drawing,cp);
    LinearLayout tools=row();tools.addView(btn("↶",()->drawing.undo()),new LinearLayout.LayoutParams(dp(45),dp(42)));tools.addView(btn("Borrador",()->{eraser=!eraser;status.setText(eraser?"Borrador activado":"Lápiz activado");}),new LinearLayout.LayoutParams(-2,dp(42)));onionButton=btn("Guía ✓",()->{onion=!onion;onionButton.setText(onion?"Guía ✓":"Guía ○");drawing.invalidate();});tools.addView(onionButton,new LinearLayout.LayoutParams(-2,dp(42))); Spinner sizes=new Spinner(this);String[] sz={"3 px","6 px","10 px","16 px","24 px"};ArrayAdapter<String> sa=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,sz);sizes.setAdapter(sa);sizes.setSelection(1);sizes.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?>p){}public void onItemSelected(android.widget.AdapterView<?>p,View v,int pos,long id){brush=new int[]{3,6,10,16,24}[pos];}});tools.addView(sizes,new LinearLayout.LayoutParams(0,dp(42),1));root.addView(tools);
    LinearLayout colors=row();for(int c:palette){View sw=new View(this);sw.setBackgroundColor(c);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(27),1);p.setMargins(dp(2),dp(2),dp(2),dp(2));sw.setOnClickListener(v->{color=c;eraser=false;drawing.invalidate();});colors.addView(sw,p);}root.addView(colors);
    LinearLayout timetop=row();frameCount=text("Cuadros",12);frameCount.setGravity(Gravity.CENTER_VERTICAL);timetop.addView(frameCount,new LinearLayout.LayoutParams(0,dp(27),1));timetop.addView(btn("＋ Cuadro",()->addFrame()),new LinearLayout.LayoutParams(-2,dp(36)));timetop.addView(btn("Duplicar",()->duplicateFrame()),new LinearLayout.LayoutParams(-2,dp(36)));timetop.addView(btn("−",()->deleteFrame()),new LinearLayout.LayoutParams(dp(48),dp(36)));root.addView(timetop);
